import { addFilter } from '../application/hooks.js';

addFilter('core.profile.entries', (entries) => [
  ...entries,
  {
    id: 'studio-profile',
    pluginId: 'page-studio-note',
    title: 'Studio note',
    description: 'Open the studio page',
    href: '/studio-note',
  },
]);

import { requireAuth } from '../../../middleware/requireAuth.js';
import { requirePermission } from '../../../middleware/requirePermission.js';
import { requirePluginEnabled } from '../../../middleware/requirePluginEnabled.js';

router.use(
  requireAuth,
  requirePermission('loyalty'),
  requirePluginEnabled('commerce-loyalty'),
);

import { registerPluginService, getPluginService } from '../application/pluginServices.js';

registerPluginService('journal-api', { append, query });

const journal = await getPluginService('journal-api');
if (!journal) return;
await journal.append(event);

import { addFilter } from '../../plugins/application/hooks.js';

addFilter('core.profile.entries', (entries) => [
  ...entries,
  {
    id: 'studio-profile',
    pluginId: 'page-studio-note',
    title: 'Studio note',
    description: 'A page from the studio-note plugin.',
    href: '/studio-note',
  },
]);

export async function priceLoyaltyIfEnabled(client, params) {
  if (!(await isPluginEffectivelyEnabled('commerce-loyalty'))) {
    return { loyaltyCredit: 0, loyaltyEarn: 0, earnStatus: 'void', incompatibleWithVoucher: Boolean(params.voucherOfferType) };
  }
  return buildLoyaltyPricingForCheckout(client, params);
}
